import{z as l,x as A,o as r,c as p,q as o,j as i,D as t,d as e,s as n,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"缓存分区与 QoS","description":"","frontmatter":{"title":"缓存分区与 QoS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cache-partition-qos.md","filePath":"cs/cache-partition-qos.md","lastUpdated":1791413859000}'),d={name:"cs/cache-partition-qos.md"};function c(h,a,m,C,F,u){const s=A("Mermaid");return r(),p("div",null,[a[2]||(a[2]=o('<h1 id="缓存分区与-qos" tabindex="-1">缓存分区与 QoS <a class="header-anchor" href="#缓存分区与-qos" aria-label="Permalink to &quot;缓存分区与 QoS&quot;">​</a></h1><div class="epigraph"><p>共享 LLC 上，贪心的扫描核会用 LRU 占满所有路；按核切路或按效用切容量，才能让延迟敏感的核保住命中。</p><footer>—— 据 Qureshi and Patt, Utility-Based Cache Partitioning, MICRO 2006 整理</footer></div><p><a href="/cs/prefetch-timing-pollution">上一课</a> 的错预取会污染共享层。即使预取关掉，一个核的工作集也能通过 <a href="/cs/lru-plru">LRU</a> 把另一个核的热块挤走——这是多核 QoS，不是单核替换能单独解决的。本课不重调 \\(k\\)。缺口是<strong>分区：把 LLC 的路或组按核（或 VM）切开，按效用而不是按瞬时 LRU 竞争。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两核共享 16 路 LLC。核 A 扫描大数组，核 B 跑延迟敏感的工作集刚好 4 路。LRU 下 A 的一次性块不断当 MRU，B 的命中率崩。缺口不是 MESI（副本仍然正确），而是<strong>分配：给 B 保留若干路，A 只能在自己的份额里替换。</strong></p><p><span class="marginnote">直觉类比：共享 LLC 像自助餐厅的公用长桌——LRU 规则下谁吃得快谁铺满全桌（扫描核）；分区就是给常客留卡座（按效用留路），别人再挤也占不走。</span></p><p><span class="marginnote">UCP：用每路命中曲线估计「再给这个核一路能减少多少缺失」，按边际效用切。CAT 一类的架构接口把某些路绑到某类 QoS 域。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>路分区：每组内若干 way 属于某核，替换只在自己的 way 子集里踢。组分区/页着色：不同核用不同组，类似把 LLC 切成 bank。监控：每核 miss 计数、占用计数。效用：试探性占用增加，看 miss 下降是否足够。</p><p><span class="marginnote">术语翻译：路掩码就是「每核一张可坐座位表」——16 位位串里哪几位置 1，这核的替换就只许踢那几路；CAT 一类接口把它从微结构技巧做成了系统软件可配的寄存器。</span></p>',10)),(r(),i(B,null,{default:t(()=>[n(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHR%5B%22%E5%85%B1%E4%BA%AB%20LLC%22%5D%20--%3E%20LRU%5B%22%E6%97%A0%E5%88%86%E5%8C%BA%EF%BC%9A%E6%89%AB%E6%8F%8F%E8%80%85%E5%8D%A0%E6%BB%A1%22%5D%0A%20%20SHR%20--%3E%20WAY%5B%22%E6%8C%89%E6%A0%B8%E9%99%90%E5%88%B6%E5%8F%AF%E6%9B%BF%E6%8D%A2%E8%B7%AF%22%5D%0A%20%20WAY%20--%3E%20QOS%5B%22%E5%BB%B6%E8%BF%9F%E6%95%8F%E6%84%9F%E6%A0%B8%E4%BF%9D%E4%BD%8F%E7%83%AD%E5%9D%97%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("分区降低总吞吐也可能：把路给「效用低」的核会浪费。UCP 的目标通常是总缺失最少或加权 CPI。与 "),E("a",{href:"/cs/rrip-dead-block"},"RRIP"),e(" 可叠：分区内仍用 RRIP。预取填入算在该核配额里，否则预取变成占路攻击。")],-1)),(r(),i(B,null,{default:t(()=>[n(s,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20MON%5B%22%E8%AF%95%E6%B5%8B%3A%20%E6%AF%8F%E6%A0%B8%E5%86%8D%E6%B7%BB%E4%B8%80%E8%B7%AF%E8%83%BD%E7%9C%81%E5%A4%9A%E5%B0%91%E7%BC%BA%E5%A4%B1%22%5D%20--%3E%20CURVE%5B%22%E5%BE%97%E6%AF%8F%E6%A0%B8%E6%95%88%E7%94%A8%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20CURVE%20--%3E%20GIVE%5B%22%E8%B4%AA%E5%BF%83%E6%8A%8A%E6%AF%8F%E4%B8%80%E8%B7%AF%E7%BB%99%E6%94%B6%E7%9B%8A%E6%9C%80%E9%AB%98%E7%9A%84%E6%A0%B8%22%5D%0A%20%20GIVE%20--%3E%20MASK%5B%22%E5%86%99%E5%90%84%E6%A0%B8%E8%B7%AF%E6%8E%A9%E7%A0%81%22%5D%0A%20%20MASK%20--%3E%20ENF%5B%22%E6%9B%BF%E6%8D%A2%E5%8F%AA%E5%9C%A8%E8%87%AA%E5%B7%B1%E8%B7%AF%E5%86%85%E8%B8%A2%22%5D%0A%20%20CYC%5B%22%E5%91%A8%E6%9C%9F%E9%87%8D%E6%B5%8B%22%5D%20--%3E%20MON%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">常见误区：初学者容易以为分区必然提升总吞吐——把路分给效用低的核是纯浪费；它的目标是保住延迟敏感核的命中或压低总缺失，有时宁可牺牲整体容量利用率。</span></p><p>虚拟机与容器把「核」换成 class of service，硬件计数器给 hypervisor 看。这是微结构对系统软件的接口，不是新的一致性状态。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Linux 的 resctrl 用法教程。也不把网络带宽的 QoS 混进来。压缩可以在同一分区里装更多有效块，下一课。安全上，分区也减少某些跨核缓存侧信道，后课 Prime+Probe 会引用，本课只从性能动机讲。</p><p>后课默认：共享 LLC 可以按核切路。切完之后，行里是否还能用压缩多装点数据，是下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>共享 LLC 的 LRU 会被扫描者占满；路分区按效用分配容量。</li><li>预取与替换都在配额内记账。</li><li>行内压缩提高有效容量，是下一课。</li><li>出处：Qureshi and Patt, <em>MICRO</em>, 2006。</li></ul>',7))])}const L=l(d,[["render",c]]);export{D as __pageData,L as default};
